mapper.select:
SELECT b.id, b.be_unauth,b.be_lock, b.button_name, b.menu_id, b.sub_menu, b.note, api.req_method, api.req_url,sbp.id as perm_id, sbp.perm_action, sbp.action_ref FROM sys_button_tenant b LEFT JOIN sys_resource_api_tenant api ON b.id = api.resource_id AND api.resource_type = 'BUTTON' LEFT JOIN sys_business_perm_tenant sbp on sbp.button_id = b.id
AND b.menu_id = #{menuId, jdbcType=VARCHAR}
AND (b.id LIKE CONCAT('%',#{keyword,jdbcType=CHAR},'%') OR b.button_name LIKE CONCAT('%',#{keyword,jdbcType=CHAR},'%') OR api.req_url LIKE CONCAT('%',#{keyword,jdbcType=CHAR},'%') OR sbp.perm_action LIKE CONCAT('%',#{keyword,jdbcType=CHAR},'%') OR sbp.action_ref LIKE CONCAT('%',#{keyword,jdbcType=CHAR},'%'))
ORDER BY api.req_url ASC LIMIT #{offset,jdbcType=INTEGER}, #{limit,jdbcType=INTEGER}
